create function public.runtime_credentials(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'role',role,'policy',credential_policy,'credentialVersion',credential_version)from public.memberships where id=(p->>'userId')::uuid and active$$;
create function public.runtime_reauthenticated(p jsonb)returns void language sql security definer set search_path='' as $$update private.sessions set reauthenticated_at=now()where token_hash=p->>'hash' and revoked_at is null$$;
create function public.prepare_credential_action(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare m public.memberships;begin select * into m from public.memberships where id=(p->>'userId')::uuid;if m.id<>auth.uid() and not(private.role()='owner' and m.role='administrator' or m.school_id=private.school()and(private.role()='administrator' and m.role in ('teacher','student')or private.role()='teacher'and m.role='student'and private.student_access(m.id)))then raise exception 'FORBIDDEN' using errcode='42501';end if;if m.id=auth.uid()and private.active_attempt()then raise exception 'ACTIVE_ATTEMPT_RESTRICTED';end if;if m.id<>auth.uid()and length(coalesce(p->>'reason',''))=0 then raise exception 'REASON_REQUIRED';end if;return jsonb_build_object('id',m.id,'role',m.role,'policy',m.credential_policy);end$$;
create function public.runtime_credentials_revoke(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare m public.memberships;actor public.memberships;begin select * into m from public.memberships where id=(p->>'userId')::uuid for update;select * into actor from public.memberships where id=(p->>'actorId')::uuid;update public.memberships set credential_version=credential_version+1,must_change_password=case when m.id=actor.id then false else m.role<>'student'end where id=m.id;update private.sessions set revoked_at=now()where user_id=m.id;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action,reason)values(m.school_id,actor.id,actor.role,m.id,'account.credentials.revoked',p->>'reason');end$$;
create function public.change_login(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();ln text:=lower(p->>'loginId');begin perform private.require_access(s);if private.role()<>'student'or private.active_attempt()then raise exception 'FORBIDDEN' using errcode='42501';end if;if not exists(select 1 from private.sessions where user_id=auth.uid()and reauthenticated_at>now()-interval '5 minutes'and revoked_at is null)then raise exception 'RECENT_REAUTH_REQUIRED';end if;if ln!~'^[a-z0-9._-]{3,64}$'or ln in ('admin','owner','root','support')then raise exception 'INVALID_LOGIN';end if;perform 1 from public.memberships where id=auth.uid()for update;update private.login_identifiers set current=false where user_id=auth.uid()and current;insert into private.login_identifiers values(s,ln,p->>'loginId',auth.uid(),true);perform private.audit(s,'account.login.changed',auth.uid(),null,jsonb_build_object('loginId',p->>'loginId'));end$$;
create function public.runtime_owner_lookup(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',id,'credentialVersion',credential_version,'role',role,'policy',credential_policy,'credentialVersion',credential_version)from public.memberships where role='owner'and active and id=(p->>'userId')::uuid$$;
revoke execute on function public.runtime_credentials(jsonb),public.runtime_reauthenticated(jsonb),public.runtime_credentials_revoke(jsonb),public.runtime_owner_lookup(jsonb)from public,anon,authenticated;
grant execute on function public.runtime_credentials(jsonb),public.runtime_reauthenticated(jsonb),public.runtime_credentials_revoke(jsonb),public.runtime_owner_lookup(jsonb)to service_role;
revoke execute on function public.prepare_credential_action(jsonb),public.change_login(jsonb)from public,anon,authenticated;grant execute on function public.prepare_credential_action(jsonb),public.change_login(jsonb)to authenticated;
